import { SubtleButton } from '@/components/buttons/SubtleButton';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import ImportIcon from '@/components/icons/file/ImportIcon';
import AddShiftForm from '../forms/addShift/AddShiftForm';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { useNavigate } from 'react-router-dom';
import { ArrowLeftIcon } from 'lucide-react';
// import { ArrowLeftIcon } from 'lucide-react';

export default function AddShiftPage() {
    const navigate = useNavigate();
    const handleCancel = () => {
        navigate('/human-resources/shifts');
    };
    return (
        <div className="mt-6 w-full">
            <div className="flex flex-row justify-between mb-6">
                <UnderlineHeading text="اضافة وردية" />
                <div className="flex flex-row gap-4">

                    <SubtleButton className="bg-primery-blue-50 text-base font-medium leading-[125%] text-primery-blue-500 border border-primery-blue-50">
                        <ImportIcon />
                        استيراد ملف بيانات
                    </SubtleButton>
                    <PrimaryButton
                        onClick={handleCancel}
                        className="w-full h-10 text-base bg-transparent text-black leading-5 tracking-normal py-[10px] font-medium border border-red-error-50"
                    >
                        العودة 
                        <ArrowLeftIcon />
                    </PrimaryButton>
                </div>
            </div>
            <AddShiftForm />
        </div>
    );
}
